"""Build the accessible diagram navigator. SVG rendering is local and dependency-free."""
from html import escape as esc
from technical_diagrams import VIEW_TYPES, ICONS

READINGS = {
    'system': ['The operator uses the browser. Public HTTPS leads to Netlify; the SSH tunnel leads to Hospital. Netlify has no Hospital API connection.', 'Hospital sends 21 ciphertexts and a public key to the risk service. The service returns Enc(z); only Hospital decrypts.', 'Hospital writes AES-GCM payloads to its vault. The service loads public model weights. Both containers share a trusted-admin host.'],
    'deployment': ['The operator tunnels to VM loopback port 8080. Hospital and service communicate on the Docker network using mutual TLS 1.3 at port 8443.', 'The vault volume stores ciphertext envelopes. The external AES key is mounted only into Hospital. External TLS files are scoped per container.', 'The Paillier private key is generated in Hospital memory. Netlify is separate; final Community Cloud execution evidence is not established by a topology drawing.'],
    'hospital': ['Read the synthetic evaluation, select its input and validate the 21 integer feature codes. Invalid input returns HTTP 400.', 'Encrypt the features, call the authenticated risk service and validate/decrypt its response. Transport or response-protocol errors return HTTP 502.', 'Apply sigmoid and the validation threshold. Save the encrypted synthetic evaluation in the vault before returning risk, factors and timings.'],
    'service': ['TLS client authentication precedes HTTP handling. HTTP checks reject unsupported routes, sizes and content types; protocol/model validation rejects invalid messages.', 'Validate public-key and ciphertext groups plus overflow bounds, then compute and re-randomize Enc(B + sum(W[i] * x[i])). No private Paillier key is held.', 'If audit mode is enabled, capture the exact wire bytes and metadata before HTTP 200. Evidence-storage failure returns HTTP 503; otherwise return Enc(z).'],
    'protocol': ['Browser sends a synthetic evaluation to Hospital. Hospital validates the integers and encrypts each feature.', 'Hospital sends the ciphertext request to the service over mutual TLS 1.3. The service computes Enc(z) and completes optional audit capture before responding.', 'Hospital decrypts z, divides by 10^9 and applies sigmoid/threshold. It stores an AES-GCM result and receives append/flush/fsync completion.', 'Only then does Hospital return risk, contributions and timings to the browser. The service never receives the plaintext probability.'],
    'vault': ['The in-memory payload contains synthetic, profile, input, probability, risk_high and date.', 'AES-256-GCM uses a separate external 32-byte key, a random 12-byte nonce and the request ID as associated data.', 'The persistent JSONL envelope contains visible id and nonce plus ct (ciphertext with authentication tag). The dashed reverse relation is a decrypted view, not a foreign key.', 'The Paillier private key is a different secret, kept in Hospital memory; it is not stored in the vault.'],
    'data-model': ['STATE CATALOG has logical key cve_ent. It relates one-to-many to STATE_YEAR_MART on state code and one-to-one to STATE GEOMETRY.', 'The mart has logical composite key (cve_ent, anio), 256 rows: 32 states across eight years. Selected columns show population, notifications, deaths, discharges, treatment and a derived rate.', 'Independent official sources are aggregated by state/year into the mart; its English presentation export supplies the public map, which looks up state geometry.', 'These are file relationships, not SQL constraints or a linked patient cohort. CDC, ENSANUT and Hospital vault records are not person-joined to the mart.'],
    'model': ['Split the public CDC survey into stratified 70/15/15 subsets with seed 2026.', 'Fit scaling and logistic regression only on training. Use validation to choose the threshold; freeze the model/threshold before test evaluation.', 'Export folded/quantized parameters and report held-out metrics. Compare float, fixed-point and Paillier on the same labeled sample; repeated profiles remain a stated split limitation.'],
    'forecast': ['Read 222 aggregate weekly series and reject missing/non-finite or nonweekly calendars.', 'Within rolling origins, compare seasonal naive with ETS. Select using SMAPE with an MAE tie-break, then fit the selected model and forecast 11 bridge plus 52 display weeks.', 'Apply fallback and national-to-region-to-state reconciliation. A separate outer evaluation reruns the complete pipeline at two historical origins.', 'Export point forecasts, exploratory bands and evaluation to public JSON. The dashboard requires a cost and source for budget scenarios; no patient data or homomorphic screening is involved.'],
    'evidence': ['Build a clean identifiable runtime and record code/model hashes. Measure the real target and preserve versioned process/API metrics plus VM screenshots.', 'Keep the original audit bundle, and independently collect human-owned lab, review, video and approved AI-use records.', 'The final package gate branches to DRAFT with missing items or a final ZIP/manifest. The registered leader submits after all four review; machine checks alone do not establish external facts.']
}


def build_page(diagrams, repo, baseline, heights):
    nav=[]; panels=[]
    nav_icons={'system':'container','deployment':'server','hospital':'hospital','service':'server','protocol':'split','vault':'lock','data-model':'database','model':'model','forecast':'chart','evidence':'shield'}
    for i,d in enumerate(diagrams):
        key=d['id'];title,kind=VIEW_TYPES[key];active=i==0
        nav.append(f'<button role="tab" id="tab-{key}" aria-controls="{key}" aria-selected="{str(active).lower()}" tabindex="{0 if active else -1}" data-view="{key}"><svg class="nav-icon" viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{ICONS[nav_icons[key]]}</svg><span>{title}<small>{kind}</small></span></button>')
        sources=' · '.join(f'<a href="{repo}/blob/{baseline}/{p}">{esc(p)}</a>' for p in d['source'])
        steps=''.join(f'<li>{esc(text)}</li>' for text in READINGS[key])
        panels.append(f'''<section id="{key}" role="tabpanel" aria-labelledby="tab-{key}" class="panel" data-kind="{kind}" data-title="{title}" {'hidden' if not active else ''}>
<div class="panel-heading"><span class="view-type">{kind}</span><h2>{title}</h2><p>{d['intro']}</p></div>
<div class="canvas" role="region" tabindex="0" aria-label="{title}, scrollable diagram"><img src="assets/diagrams/{key}.svg" width="1200" height="{heights[key]}" alt="{title}: {kind}. Expand the text description below for the implementation details." loading="{'eager' if active else 'lazy'}"></div>
<div class="diagram-caption"><span>Read the notation subtitle: message, dependency and logical relationship lines have distinct meanings.</span><span>SVG · editable vector</span></div>
<details class="explanation"><summary>Read the diagram and implementation limits</summary><p>{d['note']}</p><ol>{steps}</ol><p class="sources">Source at {baseline} · {sources}</p></details></section>''')
    return '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Technical architecture · Los Antimarrulla</title><meta name="description" content="Technical architecture, sequence diagrams, flowcharts and data schemas for privacy-preserving screening."><link rel="icon" href="assets/logo.png">
<style>
:root{color-scheme:dark;--bg:#0b1426;--panel:#101d34;--line:#263753;--text:#edf3fc;--muted:#a8b9d3;--accent:#95b8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--accent);text-underline-offset:4px}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible,.canvas:focus-visible{outline:3px solid #ffc66c;outline-offset:3px}.top{padding:22px 32px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:14px;text-decoration:none;color:var(--text)}.brand img{width:42px;height:42px;border-radius:9px}.brand b{display:block;font-size:16px}.brand span,.top nav{color:var(--muted);font-size:12px}.top nav{display:flex;gap:24px}.intro{max-width:1550px;margin:0 auto;padding:28px 32px 22px;display:flex;align-items:flex-end;justify-content:space-between;gap:22px}.eyebrow{font-size:11px;letter-spacing:.14em;color:var(--accent);text-transform:uppercase}h1{font-size:32px;letter-spacing:-.025em;margin:5px 0 6px;line-height:1.15}.intro p{margin:0;color:var(--muted);max-width:700px}.runtime{font:11px ui-monospace,SFMono-Regular,monospace;color:var(--muted);white-space:nowrap}.workspace{max-width:1550px;display:grid;grid-template-columns:236px minmax(0,1fr);gap:22px;padding:0 32px 32px;margin:auto}.rail{border-top:1px solid var(--line);padding-top:12px}.rail-label{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);padding:4px 12px 12px}.tabs{display:grid;gap:4px}.tabs button{display:flex;gap:12px;align-items:center;text-align:left;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--muted);padding:12px 10px;line-height:1.25;font-size:13px}.tabs button:hover{background:#152640}.tabs button[aria-selected=true]{border-color:#446ca8;background:#1c3455;color:white}.nav-icon{width:22px;height:22px;flex:none;color:var(--accent)}.tabs small{display:block;font-size:10px;margin-top:5px;opacity:.7}.rail-note{font-size:11px;color:var(--muted);border-top:1px solid var(--line);margin-top:18px;padding-top:14px}.viewer{min-width:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--panel)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 18px;border-bottom:1px solid var(--line);background:#14243e}.tools,.downloads{display:flex;gap:6px;align-items:center}.toolbar button,.toolbar a{border:1px solid #364b6b;border-radius:6px;background:transparent;color:var(--text);font:12px system-ui,sans-serif;padding:6px 10px;text-decoration:none;white-space:nowrap}.toolbar button:hover,.toolbar a:hover{background:#24416b}.toolbar output{font:11px ui-monospace,monospace;min-width:42px;text-align:center}.panel[hidden]{display:none}.panel-heading{padding:21px 24px 17px}.view-type{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--accent)}h2{font-size:24px;letter-spacing:-.02em;margin:4px 0 7px}.panel-heading p{color:var(--muted);font-size:13px;margin:0;max-width:900px}.canvas{background:#0a1324;overflow:auto;max-height:78vh;min-height:240px;overscroll-behavior:contain;scrollbar-color:#3d5683 #0a1324}.canvas img{display:block;height:auto;max-width:none}.diagram-caption{display:flex;justify-content:space-between;gap:16px;padding:10px 20px;background:#14243e;color:var(--muted);font-size:10px}.explanation{padding:16px 24px;font-size:13px}.explanation summary{cursor:pointer;color:var(--accent);font-size:12px}.explanation p,.explanation ol{color:var(--muted)}.explanation li{margin:8px 0}.sources{font-size:11px;overflow-wrap:anywhere}.footer{max-width:1550px;margin:auto;padding:0 32px 30px;color:var(--muted);font-size:11px}.footer a{white-space:nowrap}@media(max-width:900px){.workspace{grid-template-columns:190px minmax(0,1fr);gap:14px;padding:0 20px 24px}.top,.intro{padding-left:20px;padding-right:20px}.downloads a{font-size:11px}.runtime{display:none}}@media(max-width:680px){.top{padding:14px 16px}.top nav a:first-child{display:none}.top nav{gap:12px}.brand b{font-size:14px}.brand img{width:35px;height:35px}.brand span{font-size:10px}.intro{padding:22px 16px 18px}h1{font-size:27px}.intro p{font-size:13px}.workspace{display:block;padding:0 12px 20px}.rail{padding:0;border:0;margin-bottom:12px}.rail-label,.rail-note{display:none}.tabs{display:flex;overflow-x:auto;gap:6px;padding:2px 0 8px}.tabs button{flex-shrink:0;padding:9px 10px;border-color:var(--line)}.tabs small{display:none}.nav-icon{width:17px;height:17px}.toolbar{padding:10px;flex-wrap:wrap;gap:8px}.toolbar button,.toolbar a{padding:6px 8px}.panel-heading{padding:17px 16px}h2{font-size:22px}.canvas{max-height:68vh}.diagram-caption{padding:9px 14px}.diagram-caption span:last-child{display:none}.explanation{padding:15px 16px}.footer{padding:0 16px 24px}}@media print{@page{size:A3 landscape;margin:10mm}.top,.intro,.rail,.toolbar,.footer,.explanation{display:none}.workspace{display:block;padding:0}.viewer{border:0}.panel[hidden]{display:block!important}.panel{break-after:page}.panel-heading{color:#20344d}.panel-heading p{color:#526780}.canvas{max-height:none;overflow:visible}.canvas img{width:100%!important}.diagram-caption{color:#526780;background:white}}
</style></head><body>
<header class="top"><a class="brand" href="index.html"><img src="assets/logo.png" alt="Los Antimarrulla logo"><span><b>Los Antimarrulla</b>IBM Z Datathon 2026 · AI Secured</span></a><nav aria-label="Project"><a href="index.html#plan">Delivery plan</a><a href="forecast.html">Forecast</a><a href="''' + repo + '''">Repository ↗</a></nav></header>
<div class="intro"><div><span class="eyebrow">Engineering documentation / 10 views</span><h1>Technical architecture</h1><p>Choose the view that answers your question: deployment, messages, decisions or data relationships.</p></div><span class="runtime">Runtime reference / ''' + baseline + '''</span></div>
<main class="workspace"><aside class="rail"><div class="rail-label">System views</div><nav class="tabs" role="tablist" aria-label="Technical diagram" aria-orientation="vertical">''' + ''.join(nav) + '''</nav><p class="rail-note">Actor, component, decision, document and database symbols have distinct roles.<br><br>Scroll within the canvas. Use Fit width for an overview, or Open SVG for browser zoom.</p></aside><div class="viewer"><div class="toolbar"><div class="tools" aria-label="Diagram zoom"><button id="fit">Fit width</button><button id="zoom-out" aria-label="Zoom out">−</button><output id="zoom" aria-live="polite">100%</output><button id="zoom-in" aria-label="Zoom in">+</button></div><div class="downloads"><a id="open-svg" href="assets/diagrams/system.svg" target="_blank" rel="noopener">Open SVG ↗</a><a id="download-svg" href="assets/diagrams/system.svg" download>Download SVG ↓</a></div></div>''' + ''.join(panels) + '''</div></main>
<footer class="footer">Documentation of the implemented design; final English LinuxONE/provider evidence remains separate. The same-host MVP trusts the VM administrator. <a href="''' + repo + '''/blob/main/docs/SYSTEM_DIAGRAMS.md">Storage dictionary and source guide ↗</a></footer>
<script>
const panels=[...document.querySelectorAll('.panel')],tabs=[...document.querySelectorAll('[role=tab]')];let current='system',zoom=100;
function resize(){const panel=document.getElementById(current),canvas=panel.querySelector('.canvas');panel.querySelector('img').style.width=`${Math.max(canvas.clientWidth,960)*zoom/100}px`;document.getElementById('zoom').value=`${Math.round(zoom)}%`}
function show(id,focus=false){if(!panels.some(p=>p.id===id))id='system';current=id;zoom=100;for(const p of panels)p.hidden=p.id!==id;for(const t of tabs){const selected=t.dataset.view===id;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1;if(selected&&focus)t.focus()}for(const key of ['open-svg','download-svg'])document.getElementById(key).href=`assets/diagrams/${id}.svg`;resize();const canvas=document.getElementById(id).querySelector('.canvas');canvas.scrollTo(0,0)}
for(const t of tabs){t.addEventListener('click',()=>{show(t.dataset.view);history.replaceState(null,'','#'+current)});t.addEventListener('keydown',e=>{let i=tabs.indexOf(t);if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+tabs.length)%tabs.length;show(tabs[i].dataset.view,true);history.replaceState(null,'','#'+current)}})}
document.getElementById('zoom-in').onclick=()=>{zoom=Math.min(225,zoom+25);resize()};document.getElementById('zoom-out').onclick=()=>{zoom=Math.max(25,zoom-25);resize()};document.getElementById('fit').onclick=()=>{const w=document.getElementById(current).querySelector('.canvas').clientWidth;zoom=w/Math.max(w,960)*100;resize()};addEventListener('hashchange',()=>show(location.hash.slice(1)));addEventListener('resize',resize);show(location.hash.slice(1)||'system');
</script></body></html>
'''
